import pandas as pd
import numpy as np
import os
from pathlib import Path

REPO_ROOT = Path(__file__).resolve().parents[2]
DATA_DIR = Path(os.environ.get("GCI_DATA_DIR", REPO_ROOT / "data"))

def build_customer_360():
    np.random.seed(42) # Guarantees total reproducibility across runs
    
    # 1. Load the synthetic data generated by step6 from the data folder
    customers = pd.read_csv(DATA_DIR / 'synthetic_customers.csv')
    transactions = pd.read_csv(DATA_DIR / 'synthetic_transactions.csv')
    
    # 2. Prevent Label Leakage: Aggregate strictly on PREDICTED category (not ground truth)
    # The observation window is 6 months (Jan-Jun), so we multiply by 2 to annualize
    tx_agg = transactions.groupby(['customer_id', 'predicted_category'])['amount'].sum().unstack(fill_value=0) * 2
    
    # Clean up column names to match contract expected inputs
    tx_agg.columns = [f'annual_{col.lower().replace(" ", "_")}_spend' for col in tx_agg.columns]
    tx_agg = tx_agg.reset_index()
    
    # 3. Merge aggregates back to the main customer table
    c360 = pd.merge(customers, tx_agg, on='customer_id', how='left')
    spend_cols = [col for col in c360.columns if 'annual_' in col and 'spend' in col]
    c360[spend_cols] = c360[spend_cols].fillna(0)
    
    # 4. Digital Engagement & Meta-Features
    tx_counts = transactions.groupby('customer_id').size().reset_index(name='transaction_count_6m')
    c360 = pd.merge(c360, tx_counts, on='customer_id', how='left').fillna({'transaction_count_6m': 0})
    
    c360['digital_logins_90d'] = np.where(
        c360['has_digital_banking'], 
        np.random.randint(5, 50, len(c360)), 
        0
    )
    
    # 5. Enforce Physical Reality Constraints
    # Non-drivers must have zero fuel spend and zero automotive spend
    c360.loc[~c360['has_vehicle'], 'annual_fuel_spend'] = 0.0
    c360.loc[~c360['has_vehicle'], 'annual_automotive_spend'] = 0.0

    # 6. Set Governance Cutoff Date
    c360['data_cutoff_date'] = '2026-06-30'
    
    return c360

# Execute and save
df_c360 = build_customer_360()

# Ensure data directory exists
DATA_DIR.mkdir(parents=True, exist_ok=True)
df_c360.to_csv(DATA_DIR / "customer_360.csv", index=False)

print(f"Success: Saved customer_360.csv to {DATA_DIR}! Shape: {df_c360.shape}")